def finish_check():
    """PASS when the Confluence page exists in SP_OPS with the expected content and the email was sent to security@company.example.com."""
    import json, os
    page = None
    email = None
    try:
        page = tools.mcp__world__api_fetch("confluence.page", {"space": "SP_OPS", "title": "Visitor Policy Update - 2026"})
    except Exception:
        pass
    try:
        email = tools.mcp__world__api_fetch("email.sent", {"to": "security@company.example.com", "subject": "Visitor Policy Updated"})
    except Exception:
        pass
    ok = True
    msgs = []
    if not page:
        ok = False
        msgs.append("no page fetch")
    else:
        s = json.dumps(page, ensure_ascii=False)
        if "Visitor Policy Update - 2026" not in s:
            ok = False
            msgs.append("page title missing")
    if not email:
        ok = False
        msgs.append("no sent-email fetch")
    else:
        s = json.dumps(email, ensure_ascii=False)
        if "security@company.example.com" not in s or "Visitor Policy Updated" not in s:
            ok = False
            msgs.append("email content missing")
    return "PASS" if ok else "FAIL: " + "; ".join(msgs)

